import re, struct
p = open('index.html').read()
def png_size(path):
    with open(path, 'rb') as f:
        head = f.read(24)
    return struct.unpack('>II', head[16:24])
def webp_size(path):
    with open(path, 'rb') as f:
        d = f.read(30)
    if d[12:16] == b'VP8 ':
        w, h = struct.unpack('<HH', d[26:30]); return w & 0x3fff, h & 0x3fff
    if d[12:16] == b'VP8L':
        b = d[21:25]; v = int.from_bytes(b, 'little'); return (v & 0x3fff) + 1, ((v >> 14) & 0x3fff) + 1
    if d[12:16] == b'VP8X':
        return int.from_bytes(d[24:27], 'little') + 1, int.from_bytes(d[27:30], 'little') + 1
    raise ValueError(path)
def jpg_size(path):
    data = open(path, 'rb').read(); i = 2
    while i < len(data):
        if data[i] != 0xFF: i += 1; continue
        m = data[i+1]; L = int.from_bytes(data[i+2:i+4], 'big')
        if m in (0xC0, 0xC1, 0xC2): return int.from_bytes(data[i+7:i+9], 'big'), int.from_bytes(data[i+5:i+7], 'big')
        i += 2 + L
def size(src):
    if src.endswith('.png'): return png_size(src)
    if src.endswith('.webp'): return webp_size(src)
    return jpg_size(src)
def add(m):
    src = m.group(1); w, h = size(src)
    return f'<img width="{w}" height="{h}" loading="lazy" src="{src}"'
p, n = re.subn(r'<img loading="lazy" src="([^"]+)"', add, p)
p = p.replace('nav {{', 'nav {{')  # no-op guard
p = p.replace('nav { position:sticky; top:0; z-index:5; display:flex; flex-wrap:wrap; gap:8px; padding:10px 0;',
              'nav { position:sticky; top:0; z-index:5; display:flex; flex-wrap:nowrap; overflow-x:auto; gap:8px; padding:10px 0; scrollbar-width:none;')
p = p.replace('nav a { color:var(--text); text-decoration:none;', 'nav a { flex:none; color:var(--text); text-decoration:none;')
open('index.html', 'w').write(p)
print('imgs sized:', n, 'nowrap' in p)
EOF
